import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { parse, stringify } from "yaml";
import { templates } from "../build-templates";

const header =
  "# Generated by scripts/build-templates.ts from agents/*.md. Edit those files, then run: pnpm templates\n";

describe("templates", () => {
  for (const [name, doc] of Object.entries(templates)) {
    it(`${name}.template.yaml is current and parses`, () => {
      const file = readFileSync(`templates/${name}.template.yaml`, "utf8");
      expect(file).toBe(header + stringify(doc, { lineWidth: 0, blockQuote: "literal" }));
      const parsed = parse(file) as {
        version: number;
        resources: Record<string, { type: string; instructions?: string }>;
      };
      expect(parsed.version).toBe(2);
      for (const r of Object.values(parsed.resources)) {
        if (r.type === "agent") {
          expect(r.instructions).toBeTruthy();
          expect(r.instructions).toContain("never");
        }
      }
    });
  }
  it("every agent instruction forbids signing, accepting a notice and stating money", () => {
    for (const n of ["ship-mate", "agency-clerk", "charter-desk"]) {
      const t = readFileSync(`agents/${n}.md`, "utf8");
      expect(t).toMatch(/never sign/i);
      expect(t).toMatch(/money/i);
      expect(t).toMatch(/Notice of Readiness/);
    }
  });
  it("the desk room has the exclusive timekeeper role and a deployer-written terms document", () => {
    const desk = (
      templates["port-call"] as {
        resources: {
          desk: { roles: Array<{ name: string; exclusive: boolean }>; docs: Array<{ name: string }> };
        };
      }
    ).resources.desk;
    expect(desk.roles.find((r) => r.name === "timekeeper")?.exclusive).toBe(true);
    expect(desk.docs.map((d) => d.name)).toContain("charter-terms");
  });
});
